def _validate_tooling_cli_paths(parser: argparse.ArgumentParser, args: argparse.Namespace) -> None:
    for attr in ("path", "previous", "current", "previous_semantic"):
        if not hasattr(args, attr):
            continue
        value = getattr(args, attr)
        if not value:
            continue
        candidate = Path(value)
        if not candidate.exists():
            parser.error(f"{args.command}: path does not exist: {value}")
        if attr == "path" and args.command not in {"lint", "semantic"} and candidate.is_dir():
            parser.error(f"{args.command}: expected a file path, got directory: {value}")
    if args.command == "lint" and getattr(args, "catalog", None):
        catalog_path = Path(args.catalog)
        if not catalog_path.exists():
            parser.error(f"{args.command}: path does not exist: {args.catalog}")


def _parse_tooling_json_argument(parser: argparse.ArgumentParser, args: argparse.Namespace, attr: str, option: str) -> dict | None:
    value = getattr(args, attr, None)
    if not value:
        return None
    try:
        payload = json.loads(value)
    except json.JSONDecodeError as exc:
        parser.error(f"{args.command}: invalid JSON for {option}: {exc.msg}")
    if not isinstance(payload, dict):
        parser.error(f"{args.command}: {option} must be a JSON object")
    return payload


def _emit_tooling_payload(payload: dict, *, as_json: bool) -> None:
    if as_json:
        print(json.dumps(payload, indent=2, sort_keys=True, default=list))
        return
    if payload.get("format") == "appgen.lint-report.v1":
        status = "ok" if payload.get("ok") else "failed"
        counts = payload.get("severity_counts", {})
        print(f"lint {status}: format={payload.get('format')} {counts}")
        if payload.get("source_mode") or payload.get("files"):
            files = tuple(payload.get("files", ()))
            print(f"source {payload.get('source_mode', 'file')}: files={len(files)}")
            for file_name in files:
                print(f"source-file {file_name}")
        stages = payload.get("stages") or {}
        if stages:
            stage_names = tuple(payload.get("stage_names") or LINT_STAGE_NAMES)
            stage_counts = " ".join(
                f"{name}={stages.get(name, {}).get('diagnostic_count', 0)}"
                for name in stage_names
            )
            print(f"stages {stage_counts}")
        migration = payload.get("migration_preview") or {}
        if migration.get("format") == "appgen.migration-plan.v1":
            changes = migration.get("changes", ())
            detected = tuple(migration.get("coverage", {}).get("detected", ()))
            print(
                "migration-preview "
                f"format={migration.get('format')} backend={migration.get('backend', 'unknown')}: "
                f"changes={len(changes)} "
                f"requires_approval={migration.get('requires_approval', False)}"
            )
            if detected:
                print(f"migration-detected {', '.join(sorted(detected))}")
        for diagnostic in payload.get("diagnostics", ()):
            print(f"{diagnostic['severity']} {diagnostic['code']}: {diagnostic['message']}")
        return
    if payload.get("format") == "appgen.semantic-model.v1":
        status = "ok" if payload.get("ok") else "failed"
        source_files = tuple(payload.get("source_files", ()))
        symbols = payload.get("symbols", {}) or {}
        diagnostics = tuple(payload.get("diagnostics", ()))
        source_set = payload.get("source_set") or {}
        symbol_coverage = payload.get("symbol_coverage") or {}
        print(
            f"semantic {status}: format={payload.get('format')} "
            f"source_mode={payload.get('source_mode', 'file')} "
            f"files={len(source_files)} symbols={len(symbols)} "
            f"tables={len(payload.get('tables', {}) or {})} views={len(payload.get('views', {}) or {})} "
            f"diagnostics={len(diagnostics)} source_set_format={source_set.get('format')}"
        )
        for file_name in source_files:
            print(f"source-file {file_name}")
        for file_name, count in sorted((payload.get("source_file_symbol_counts") or {}).items()):
            print(f"symbol-file {file_name} symbols={count}")
        if symbol_coverage:
            print(
                f"symbol-coverage format={symbol_coverage.get('format')} "
                f"required={symbol_coverage.get('required_kind_count', 0)} "
                f"detected={symbol_coverage.get('detected_kind_count', 0)} "
                f"missing={symbol_coverage.get('missing_kind_count', 0)}"
            )
        counts = payload.get("contract_counts") or {}
        if counts:
            print(
                "contract-counts "
                f"top_level={counts.get('present_top_level_field_count', 0)}/"
                f"{counts.get('required_top_level_field_count', 0)} "
                f"source_files={counts.get('source_file_count', len(source_files))} "
                f"symbol_files={counts.get('source_file_symbol_file_count', 0)}"
            )
        for diagnostic in diagnostics:
            print(f"{diagnostic['severity']} {diagnostic['code']}: {diagnostic['message']}")
        return
    if payload.get("format") == "appgen.format-result.v1":
        status = "changed" if payload.get("changed") else "ok"
        idempotent = "idempotent" if payload.get("idempotent") else "not-idempotent"
        write_status = " written" if payload.get("written") else ""
        print(
            f"format {status}: format={payload.get('format')} "
            f"{idempotent}{write_status} "
            f"organize={payload.get('organize', False)} "
            f"write_requested={payload.get('write_requested', False)} "
            f"written={payload.get('written', False)}"
        )
        if payload.get("write_path"):
            print(f"write_path {payload.get('write_path')}")
        for diagnostic in payload.get("diagnostics", ()):
            print(f"{diagnostic['severity']} {diagnostic['code']}: {diagnostic['message']}")
        return
    if payload.get("format") == "appgen.validate-report.v1":
        status = "ok" if payload.get("ok") else "failed"
        requested = tuple(payload.get("requested_targets", ()))
        app_targets = tuple(payload.get("app_targets", ()))
        semantic = payload.get("semantic_model", {})
        print(
            f"validate {status}: format={payload.get('format')} "
            f"requested={','.join(requested) or 'default'} "
            f"app_targets={','.join(app_targets) or 'none'} "
            f"semantic_format={semantic.get('format')}"
        )
        for check in payload.get("checks", ()):
            print(f"{'ok' if check['ok'] else 'fail'} {check['check']}")
            if check.get("check") == "target_compatibility":
                unknown = tuple(check.get("unknown_targets", ()))
                missing = tuple(check.get("missing_targets", ()))
                if unknown:
                    print(f"unknown-targets {', '.join(unknown)}")
                if missing:
                    print(f"missing-targets {', '.join(missing)}")
        for diagnostic in payload.get("diagnostics", ()):
            print(f"{diagnostic['severity']} {diagnostic['code']}: {diagnostic['message']}")
        return
    if payload.get("format") == "appgen.generate-report.v1":
        status = "ok" if payload.get("ok") else "failed"
        targets = tuple(payload.get("targets", ()))
        print(
            f"generate {status}: format={payload.get('format')} "
            f"generated={payload.get('generated', False)} "
            f"targets={','.join(targets) or 'default'} artifacts={len(payload.get('artifacts', ()))} "
            f"semantic_format={payload.get('semantic_model_format') or payload.get('validation', {}).get('semantic_model', {}).get('format')}"
        )
        output_dir = payload.get("output_dir")
        if output_dir:
            print(f"output_dir {output_dir}")
        manifest = payload.get("manifest")
        if manifest:
            print(f"manifest {manifest}")
        for artifact in payload.get("artifacts", ()):
            path = artifact["path"]
            if "bytes" in artifact:
                print(f"artifact {path} bytes={artifact['bytes']}")
            else:
                print(f"artifact {path}")
        for gap in payload.get("blocking_gaps", ()):
            print(f"gap {gap}")
        for diagnostic in payload.get("diagnostics", ()):
            print(f"{diagnostic['severity']} {diagnostic['code']}: {diagnostic['message']}")
        return
    if payload.get("format") == "appgen.internal-error.v1":
        print(
            f"internal-error failed: format={payload.get('format')} "
            f"code={payload.get('code')} error_type={payload.get('error_type')}: {payload.get('message')}"
        )
        return
    if payload.get("format") == "appgen.graph-suite-report.v1":
        status = "ok" if payload.get("ok") else "failed"
        kinds = tuple(payload.get("required_kinds", ()))
        formats = tuple(payload.get("formats", ()))
        kind_count = len(kinds)
        format_count = len(formats)
        print(f"graph-suite {status}: format={payload.get('format')} {kind_count} kinds, {format_count} formats")
        if kinds:
            print(f"graph-kinds {', '.join(kinds)}")
        if formats:
            print(f"graph-formats {', '.join(formats)}")
        for check in payload.get("checks", ()):
            print(f"{'ok' if check['ok'] else 'fail'} {check['check']}")
        return
    if payload.get("format") == "appgen.migration-plan.v1":
        _emit_migration_plan_text(payload)
        return
    if payload.get("format") == "appgen.nl-plan.v1":
        _emit_nl_plan_text(payload)
        return
    if payload.get("format") == "appgen.release-verifier-report.v1":
        _emit_release_verifier_text(payload)
        return
    if payload.get("format") == "appgen.designer-sync-report.v1":
        _emit_designer_sync_text(payload)
        return
    if payload.get("format") == "appgen.diagnostic-catalog.v1":
        _emit_diagnostic_catalog_text(payload)
        return
    if payload.get("format") == "appgen.diagnostic-fixture-audit.v1":
        _emit_diagnostic_fixture_audit_text(payload)
        return
    if payload.get("format") == "appgen.semantic-drift-audit.v1":
        _emit_semantic_drift_text(payload)
        return
    if payload.get("format") == "appgen.lsp-service.v1":
        _emit_lsp_service_text(payload)
        return
    if payload.get("format") == "appgen.lsp-code-action-apply.v1":
        _emit_lsp_code_action_apply_text(payload)
        return
    if payload.get("format") == "appgen.parser-golden-audit.v1":
        status = "ok" if payload.get("ok") else "failed"
        missing = tuple(payload.get("missing_constructs", ()))
        print(
            f"parser-golden {status}: "
            f"format={payload.get('format')} "
            f"fixtures={payload.get('fixture_count', 0)} "
            f"valid={payload.get('valid_fixture_count', 0)} "
            f"invalid={payload.get('invalid_fixture_count', 0)} "
            f"required={payload.get('required_construct_count', len(payload.get('constructs_required', ())))} "
            f"constructs={payload.get('covered_construct_count', len(payload.get('constructs_covered', ())))} "
            f"missing={payload.get('missing_construct_count', len(missing))}"
        )
        covered = tuple(payload.get("constructs_covered", ()))
        if covered:
            print(f"covered-constructs {', '.join(covered)}")
        if missing:
            print(f"missing-constructs {', '.join(missing)}")
        for gap in payload.get("blocking_gaps", ()):
            print(f"fail {gap['name']}: {gap.get('error', '')}")
        return
    if payload.get("format") == "appgen.dsl-language-quality.v1":
        status = "ok" if payload.get("ok") else "failed"
        antlr = payload.get("antlr_integrity", {})
        budget = payload.get("budget", {})
        checks = tuple(payload.get("checks", ()))
        print(
            f"dsl-quality {status}: format={payload.get('format')} "
            f"checks={len(checks)} antlr_ok={antlr.get('ok')} "
            f"keywords={payload.get('canonical_keyword_count')}/{budget.get('limit')} "
            f"antlr_format={antlr.get('format')} budget_format={budget.get('format')}"
        )
        for check in checks:
            print(f"{'ok' if check.get('ok') else 'fail'} {check.get('check')}")
        return
    if payload.get("format") == "appgen.dsl-antlr-integrity.v1":
        status = "ok" if payload.get("ok") else "failed"
        print(
            f"dsl-antlr {status}: format={payload.get('format')} "
            f"grammar_tokens={payload.get('grammar_token_count')} "
            f"parser_tokens={payload.get('parser_token_count')} "
            f"grammar_rules={payload.get('grammar_rule_count')} "
            f"parser_rules={payload.get('parser_rule_count')} "
            f"missing_rules={len(payload.get('missing_required_rules', ()))}"
        )
        for rule in payload.get("missing_required_rules", ()):
            print(f"missing-required-rule {rule}")
        return
    if payload.get("format") == "appgen.dsl-authoring-release-gate.v1":
        status = "ok" if payload.get("ok") else "failed"
        gates = tuple(payload.get("gates", ()))
        gaps = tuple(payload.get("blocking_gaps", ()))
        print(
            f"dsl-authoring-gate {status}: format={payload.get('format')} "
            f"decision={payload.get('decision')} gates={len(gates)} blocking_gaps={len(gaps)}"
        )
        for gate in gates:
            print(f"{'ok' if gate.get('ok') else 'fail'} {gate.get('gate')}")
        return
    if payload.get("format") == "appgen.dsl-language-service.v1":
        diagnostics = tuple(payload.get("lint", {}).get("diagnostics", ()))
        completions = tuple(payload.get("completions", ()))
        actions = tuple(payload.get("code_actions", ()))
        quality = payload.get("language_quality", {})
        counts = payload.get("service_counts", {})
        print(
            f"dsl-language-service ok: format={payload.get('format')} "
            f"diagnostics={counts.get('diagnostic_count', len(diagnostics))} "
            f"completions={counts.get('completion_count', len(completions))} "
            f"actions={counts.get('code_action_count', len(actions))} "
            f"quality_format={quality.get('format')}"
        )
        return
    if payload.get("format") == "appgen.contract-schema-catalog.v1":
        status = "ok" if payload.get("ok") else "failed"
        selected = tuple(payload.get("selected_formats", ()))
        missing = tuple(payload.get("missing_required_schema_formats", ()))
        print(
            f"contract-schema {status}: format={payload.get('format')} "
            f"schemas={payload.get('schema_count', 0)} selected={len(selected)} "
            f"missing={len(missing)}"
        )
        for schema_format in selected:
            schema = (payload.get("schemas") or {}).get(schema_format, {})
            required = tuple(schema.get("required", ()))
            print(f"schema {schema_format}: required={len(required)} properties={len(schema.get('properties', {}))}")
        for schema_format in missing:
            print(f"missing-schema {schema_format}")
        return
    if payload.get("format") == "appgen.contract-validation-report.v1":
        status = "ok" if payload.get("ok") else "failed"
        diagnostics = tuple(payload.get("diagnostics", ()))
        print(
            f"contract-validate {status}: format={payload.get('format')} "
            f"payload_format={payload.get('payload_format') or 'unknown'} "
            f"schema_format={payload.get('schema_format') or 'unknown'} "
            f"errors={len(diagnostics)}"
        )
        for diagnostic in diagnostics:
            print(f"{diagnostic['severity']} {diagnostic['code']}: {diagnostic['message']}")
        return
    if payload.get("format") == "appgen.runtime-contract-inventory.v1":
        status = "ok" if payload.get("ok") else "failed"
        print(
            f"runtime-contracts {status}: format={payload.get('format')} "
            f"runtime_formats={payload.get('runtime_format_count', 0)} "
            f"schema_promoted={payload.get('schema_promoted_runtime_format_count', 0)} "
            f"documented={payload.get('documented_runtime_format_count', 0)} "
            f"unpromoted={payload.get('unpromoted_runtime_format_count', 0)} "
            f"undocumented={payload.get('undocumented_runtime_format_count', 0)}"
        )
        modules = tuple(payload.get("modules", ()))
        print(f"modules scanned={len(modules)} pbc_paths_skipped={payload.get('pbc_paths_skipped', True)}")
        for item in tuple(payload.get("unpromoted_runtime_formats", ()))[:20]:
            print(f"unpromoted-format {item}")
        for item in tuple(payload.get("undocumented_runtime_formats", ()))[:20]:
            print(f"undocumented-format {item}")
        return
    if payload.get("format") == "appgen.explain-report.v1":
        _emit_explain_text(payload)
