                evidence["contract_schema_cli"].get("format"),
                evidence["contract_validation_cli"].get("format"),
                evidence["cli_help_surface"].get("format"),
                evidence["internal_error_exit"].get("format"),
                evidence["missing_input_exit"].get("format"),
