def _tooling_audit_component_publish_cli(tmp: Path) -> dict:
    catalog_path = tmp / "component-catalog.json"
    missing_catalog_path = tmp / "missing-component-catalog.json"
    catalog_path.write_text(json.dumps({"components": [{"name": "ExistingBox"}]}, indent=2), encoding="utf-8")

    json_exit, json_payload = _tooling_cli_json_case(
        ("component-publish", "--component", "CustomGauge", "--catalog", str(catalog_path), "--json")
    )
    text_exit, text_output = _tooling_cli_text_case(
        ("component-publish", "--component", "CustomGauge", "--catalog", str(catalog_path))
    )
    missing_exit, missing_payload = _tooling_cli_json_case(
        ("component-publish", "--component", "CustomGauge", "--catalog", str(missing_catalog_path), "--json")
    )
    patch = json_payload.get("catalog_patch", {})
    catalog = json_payload.get("catalog", {})
    text_lines = tuple(line for line in text_output.splitlines() if line.strip())
    cases = (
        {
            "case": "json_publish_patch",
            "ok": json_exit == 0
            and json_payload.get("format") == "appgen.component-publish-report.v1"
            and json_payload.get("ok") is True
            and json_payload.get("component") == "CustomGauge"
            and catalog.get("components") == ["ExistingBox"]
            and patch.get("format") == "appgen.component-catalog-patch.v1"
            and patch.get("operation") == "upsert_component"
            and patch.get("component", {}).get("icon") == "custom-gauge"
            and patch.get("before_count") == 1
            and patch.get("after_count") == 2
            and patch.get("side_effect_free") is True
            and patch.get("write_performed") is False
            and not json_payload.get("blocking_gaps"),
            "exit_code": json_exit,
        },
        {
            "case": "text_publish_markers",
            "ok": text_exit == 0
            and text_output.startswith("component-publish ok: format=appgen.component-publish-report.v1")
            and "patch_format=appgen.component-catalog-patch.v1" in text_output
            and "side_effect_free=True" in text_output
            and "write_performed=False" in text_output
            and "catalog-count before=1 after=2 existing=1" in text_output
            and "catalog-existing ExistingBox" in text_output
            and not text_output.lstrip().startswith("{"),
            "exit_code": text_exit,
        },
        {
            "case": "missing_catalog_rejected",
            "ok": missing_exit == 1
            and missing_payload.get("format") == "appgen.component-publish-report.v1"
            and missing_payload.get("ok") is False
            and "catalog_path_readable" in set(missing_payload.get("blocking_gaps", ()))
            and missing_payload.get("catalog_patch", {}).get("side_effect_free") is True
            and missing_payload.get("catalog_patch", {}).get("write_performed") is False,
            "exit_code": missing_exit,
        },
    )
    failing_cases = tuple(case["case"] for case in cases if not case["ok"])
    required_case_ids = ("json_publish_patch", "text_publish_markers", "missing_catalog_rejected")
    observed_case_ids = tuple(case["case"] for case in cases)
    missing_case_ids = tuple(case_id for case_id in required_case_ids if case_id not in observed_case_ids)
    required_text_markers = (
        "component-publish ok: format=appgen.component-publish-report.v1",
        "patch_format=appgen.component-catalog-patch.v1",
        "side_effect_free=True",
        "write_performed=False",
        "catalog-count before=1 after=2 existing=1",
        "catalog-existing ExistingBox",
    )
    missing_text_markers = tuple(marker for marker in required_text_markers if marker not in text_output)
    required_missing_catalog_blocking_gaps = ("catalog_path_readable",)
    observed_missing_catalog_blocking_gaps = tuple(missing_payload.get("blocking_gaps", ()))
    missing_catalog_blocking_gap_misses = tuple(
        gap for gap in required_missing_catalog_blocking_gaps if gap not in observed_missing_catalog_blocking_gaps
    )
    expected_exit_codes_by_case = {
        "json_publish_patch": 0,
        "text_publish_markers": 0,
        "missing_catalog_rejected": 1,
    }
    exit_codes_by_case = {
        case["case"]: case.get("exit_code")
        for case in cases
        if case["case"] in expected_exit_codes_by_case
    }
    missing_exit_code_cases = tuple(
        case_id
        for case_id, expected_exit_code in expected_exit_codes_by_case.items()
        if exit_codes_by_case.get(case_id) != expected_exit_code
    )
    ok_by_case = {
        case["case"]: case.get("ok") is True
        for case in cases
        if case["case"] in required_case_ids
    }
    missing_ok_cases = tuple(
        case_id
        for case_id in required_case_ids
        if ok_by_case.get(case_id) is not True
    )
    return {
        "format": "appgen.component-publish-cli-audit.v1",
        "ok": not failing_cases
        and not missing_case_ids
        and not missing_text_markers
        and not missing_catalog_blocking_gap_misses
        and not missing_exit_code_cases
        and not missing_ok_cases,
        "case_count": len(cases),
        "passing_case_count": sum(1 for case in cases if case["ok"]),
        "failing_case_count": len(failing_cases),
        "failing_cases": failing_cases,
        "required_case_ids": required_case_ids,
        "observed_case_ids": observed_case_ids,
        "missing_case_count": len(missing_case_ids),
        "missing_case_ids": missing_case_ids,
        "case_ids": observed_case_ids,
        "payload_format": json_payload.get("format"),
        "patch_format": patch.get("format"),
        "operation": patch.get("operation"),
        "component": json_payload.get("component"),
        "component_icon": patch.get("component", {}).get("icon"),
        "before_count": patch.get("before_count"),
        "after_count": patch.get("after_count"),
        "existing_catalog_count": catalog.get("count"),
        "side_effect_free": patch.get("side_effect_free"),
        "write_performed": patch.get("write_performed"),
        "text_exit_code": text_exit,
        "text_line_count": len(text_lines),
        "text_has_report_format": text_output.startswith("component-publish ok: format=appgen.component-publish-report.v1"),
        "text_has_patch_format": "patch_format=appgen.component-catalog-patch.v1" in text_output,
        "text_has_side_effect_markers": "side_effect_free=True" in text_output and "write_performed=False" in text_output,
        "text_has_existing_catalog": "catalog-existing ExistingBox" in text_output,
        "required_text_markers": required_text_markers,
        "missing_text_marker_count": len(missing_text_markers),
        "missing_text_markers": missing_text_markers,
        "missing_catalog_exit_code": missing_exit,
        "required_missing_catalog_blocking_gaps": required_missing_catalog_blocking_gaps,
        "missing_catalog_blocking_gaps": observed_missing_catalog_blocking_gaps,
        "missing_catalog_blocking_gap_miss_count": len(missing_catalog_blocking_gap_misses),
        "missing_catalog_blocking_gap_misses": missing_catalog_blocking_gap_misses,
        "missing_catalog_side_effect_free": missing_payload.get("catalog_patch", {}).get("side_effect_free"),
        "missing_catalog_write_performed": missing_payload.get("catalog_patch", {}).get("write_performed"),
        "expected_exit_codes_by_case": expected_exit_codes_by_case,
        "exit_codes_by_case": exit_codes_by_case,
        "missing_exit_code_case_count": len(missing_exit_code_cases),
        "missing_exit_code_cases": missing_exit_code_cases,
        "ok_by_case": ok_by_case,
        "missing_ok_case_count": len(missing_ok_cases),
        "missing_ok_cases": missing_ok_cases,
        "cases": cases,
    }


def _tooling_audit_lint_directory_cli(tmp: Path, source: str) -> dict:
    source_dir = tmp / "lint-directory"
    nested_dir = source_dir / "nested"
    catalog_path = tmp / "component-catalog.json"
    strict_component_path = tmp / "strict-component.appgen"
    catalog_component_path = tmp / "catalog-component.appgen"
    migration_current_path = tmp / "lint-migration-current.appgen"
    migration_previous_path = tmp / "lint-previous-semantic.json"
    nested_dir.mkdir(parents=True, exist_ok=True)
    first_path = source_dir / "a.appgen"
    second_path = nested_dir / "b.appgen"
    first_path.write_text(source, encoding="utf-8")
    second_path.write_text(_doctor_sample_dsl(), encoding="utf-8")
    catalog_path.write_text(json.dumps({"components": ["CustomGauge"]}, indent=2), encoding="utf-8")
    strict_component_path.write_text(
        """
app StrictComponentDemo { targets: web }
table Customer { id: int pk; name: string }
view CustomerForm for Customer {
  Main: name
  @ name UnknownWidget 0 0 4 1
}
""".strip(),
        encoding="utf-8",
    )
    catalog_component_path.write_text(_tooling_audit_component_catalog_sample(), encoding="utf-8")
    migration_previous_source = "app MigrationLint { targets: web }\ntable Customer { id: int pk }\n"
    migration_current_path.write_text(
        "app MigrationLint { targets: web }\ntable Customer { id: int pk; name: string }\n",
        encoding="utf-8",
    )
    migration_previous_path.write_text(
        json.dumps(semantic_model_dsl(migration_previous_source, source_name="previous.appgen"), indent=2, default=list),
        encoding="utf-8",
    )

    def run_json(argv: tuple[str, ...]) -> tuple[int, dict]:
        output = io.StringIO()
        with contextlib.redirect_stdout(output):
            exit_code = dsl_tooling_cli(argv)
        try:
            payload = json.loads(output.getvalue())
        except json.JSONDecodeError:
            payload = {}
        return exit_code, payload

    exit_code, payload = run_json(("lint", str(source_dir), "--strict", "--catalog", str(catalog_path), "--json"))
    normal_unknown_exit_code, normal_unknown_payload = run_json(("lint", str(strict_component_path), "--json"))
    strict_unknown_exit_code, strict_unknown_payload = run_json(
        ("lint", str(strict_component_path), "--strict", "--json")
    )
    strict_catalog_exit_code, strict_catalog_payload = run_json(
        ("lint", str(catalog_component_path), "--strict", "--catalog", str(catalog_path), "--json")
    )
    migration_exit_code, migration_payload = run_json(
        ("lint", str(migration_current_path), "--previous-semantic", str(migration_previous_path), "--json")
    )

    warning_dir = tmp / "lint-directory-warnings"
    warning_nested_dir = warning_dir / "nested"
    warning_nested_dir.mkdir(parents=True, exist_ok=True)
    (warning_dir / "a.appgen").write_text(_tooling_audit_warning_generation_sample(), encoding="utf-8")
    (warning_nested_dir / "b.appgen").write_text(_doctor_sample_dsl(), encoding="utf-8")
    warning_exit_code, warning_payload = run_json(("lint", str(warning_dir), "--json"))

    files = tuple(payload.get("files", ()))
    file_reports = tuple(payload.get("file_reports", ()))
    file_order_sorted = files == tuple(sorted(files))
    file_relative_order = tuple(str(Path(file).relative_to(source_dir)) for file in files)
    warning_files = tuple(warning_payload.get("files", ()))
    warning_diagnostics = tuple(warning_payload.get("diagnostics", ()))
    warning_severity_counts = warning_payload.get("severity_counts", {})
    warning_diagnostics_have_files = all(
        "file" in diagnostic and diagnostic["file"] in warning_files for diagnostic in warning_diagnostics
    )
    normal_unknown_diagnostics = tuple(normal_unknown_payload.get("diagnostics", ()))
    strict_unknown_diagnostics = tuple(strict_unknown_payload.get("diagnostics", ()))
    strict_catalog_diagnostics = tuple(strict_catalog_payload.get("diagnostics", ()))
    syntax_path = tmp / "syntax-stage.appgen"
    semantic_path = tmp / "semantic-stage.appgen"
    policy_path = tmp / "policy-stage.appgen"
    syntax_path.write_text("app Broken { table Missing { id: int pk ", encoding="utf-8")
    semantic_path.write_text("app SemanticStage { targets: web }\nview MissingForm for Missing { Main: id }\n", encoding="utf-8")
    policy_path.write_text(_tooling_audit_warning_generation_sample(), encoding="utf-8")
    syntax_exit_code, syntax_payload = run_json(("lint", str(syntax_path), "--json"))
    semantic_exit_code, semantic_payload = run_json(("lint", str(semantic_path), "--json"))
    policy_exit_code, policy_payload = run_json(("lint", str(policy_path), "--json"))
    normal_unknown_component_warning = (
        normal_unknown_exit_code == 0
        and normal_unknown_payload.get("ok") is True
        and normal_unknown_payload.get("strict") is False
        and any(
            item.get("code") == "AGX0404" and item.get("severity") == "warning"
            for item in normal_unknown_diagnostics
        )
    )
    strict_unknown_component_error = (
        strict_unknown_exit_code == 1
        and strict_unknown_payload.get("ok") is False
        and strict_unknown_payload.get("strict") is True
        and any(
            item.get("code") == "AGX0404" and item.get("severity") == "error"
            for item in strict_unknown_diagnostics
        )
    )
    strict_catalog_component_success = (
        strict_catalog_exit_code == 0
        and strict_catalog_payload.get("ok") is True
        and strict_catalog_payload.get("strict") is True
        and strict_catalog_payload.get("component_catalog", {}).get("components") == ["CustomGauge"]
        and not any(item.get("code") == "AGX0404" for item in strict_catalog_diagnostics)
    )
    migration_preview = migration_payload.get("migration_preview") or {}
    migration_lint_success = (
        migration_exit_code == 0
        and migration_payload.get("format") == "appgen.lint-report.v1"
        and migration_preview.get("format") == "appgen.migration-plan.v1"
        and migration_preview.get("backend") == "postgresql"
        and "added_field" in set(migration_preview.get("coverage", {}).get("detected", ()))
    )
    stage_separation = {
        "syntax": syntax_exit_code == 1 and syntax_payload.get("stages", {}).get("syntax", {}).get("error", 0) >= 1,
        "semantic": semantic_exit_code == 1
        and semantic_payload.get("stages", {}).get("semantic", {}).get("error", 0) >= 1,
        "policy": policy_exit_code == 0 and policy_payload.get("stages", {}).get("policy", {}).get("warning", 0) >= 1,
    }
    scenario_results = (
        {
            "id": "strict_directory_json",
            "ok": exit_code == 0 and payload.get("format") == "appgen.lint-report.v1",
            "exit_code": exit_code,
            "payload_format": payload.get("format"),
        },
        {
            "id": "warning_directory_files",
            "ok": warning_diagnostics_have_files,
            "exit_code": warning_exit_code,
            "payload_format": warning_payload.get("format"),
            "diagnostic_count": len(warning_diagnostics),
        },
        {
            "id": "normal_unknown_component_warning",
            "ok": normal_unknown_component_warning,
            "exit_code": normal_unknown_exit_code,
            "payload_format": normal_unknown_payload.get("format"),
            "diagnostic_codes": tuple(item.get("code") for item in normal_unknown_diagnostics),
        },
        {
            "id": "strict_unknown_component_error",
            "ok": strict_unknown_component_error,
            "exit_code": strict_unknown_exit_code,
            "payload_format": strict_unknown_payload.get("format"),
            "diagnostic_codes": tuple(item.get("code") for item in strict_unknown_diagnostics),
        },
        {
            "id": "strict_catalog_component_success",
            "ok": strict_catalog_component_success,
            "exit_code": strict_catalog_exit_code,
            "payload_format": strict_catalog_payload.get("format"),
            "catalog_components": tuple(strict_catalog_payload.get("component_catalog", {}).get("components", ())),
        },
        {
            "id": "previous_semantic_migration_preview",
            "ok": migration_lint_success,
            "exit_code": migration_exit_code,
            "payload_format": migration_payload.get("format"),
            "detected": tuple(migration_preview.get("coverage", {}).get("detected", ())),
        },
        {
            "id": "stage_separation_profiles",
            "ok": all(stage_separation.values()),
            "exit_code": 0 if all(stage_separation.values()) else 1,
            "profiles": tuple(name for name, ok in stage_separation.items() if ok),
        },
        {
            "id": "directory_file_order_and_reports",
            "ok": file_order_sorted and len(file_reports) == 2,
            "exit_code": exit_code,
            "payload_format": payload.get("format"),
            "file_relative_order": file_relative_order,
        },
    )
    failing_scenarios = tuple(result["id"] for result in scenario_results if not result["ok"])
    required_scenario_ids = tuple(result["id"] for result in scenario_results)
    expected_exit_codes_by_scenario = {
        "strict_directory_json": 0,
        "warning_directory_files": 0,
        "normal_unknown_component_warning": 0,
        "strict_unknown_component_error": 1,
        "strict_catalog_component_success": 0,
        "previous_semantic_migration_preview": 0,
        "stage_separation_profiles": 0,
        "directory_file_order_and_reports": 0,
    }
    exit_codes_by_scenario = {
        result["id"]: result.get("exit_code")
        for result in scenario_results
        if result["id"] in expected_exit_codes_by_scenario
    }
    missing_exit_code_scenarios = tuple(
        scenario_id
        for scenario_id, expected_exit_code in expected_exit_codes_by_scenario.items()
        if exit_codes_by_scenario.get(scenario_id) != expected_exit_code
    )
    expected_payload_formats_by_scenario = {
        "strict_directory_json": "appgen.lint-report.v1",
        "warning_directory_files": "appgen.lint-report.v1",
        "normal_unknown_component_warning": "appgen.lint-report.v1",
        "strict_unknown_component_error": "appgen.lint-report.v1",
        "strict_catalog_component_success": "appgen.lint-report.v1",
        "previous_semantic_migration_preview": "appgen.lint-report.v1",
        "directory_file_order_and_reports": "appgen.lint-report.v1",
    }
    payload_formats_by_scenario = {
        result["id"]: result.get("payload_format")
        for result in scenario_results
        if result["id"] in expected_payload_formats_by_scenario
    }
    missing_payload_format_scenarios = tuple(
        scenario_id
        for scenario_id, expected_format in expected_payload_formats_by_scenario.items()
        if payload_formats_by_scenario.get(scenario_id) != expected_format
    )
    ok_by_scenario = {
        result["id"]: result.get("ok") is True
        for result in scenario_results
        if result["id"] in required_scenario_ids
    }
    missing_ok_scenarios = tuple(
        scenario_id
        for scenario_id in required_scenario_ids
        if ok_by_scenario.get(scenario_id) is not True
    )
    required_stage_names = ("syntax", "semantic", "policy")
    required_severity_names = ("error", "warning", "info", "hint")
    observed_stage_names = tuple(syntax_payload.get("stage_names", ()))
    observed_severity_names = tuple(syntax_payload.get("severity_names", ()))
    missing_stage_names = tuple(name for name in required_stage_names if name not in observed_stage_names)
    missing_severity_names = tuple(name for name in required_severity_names if name not in observed_severity_names)
    stage_profile_results = tuple(
        {
            "id": stage,
            "ok": ok,
            "exit_code": {"syntax": syntax_exit_code, "semantic": semantic_exit_code, "policy": policy_exit_code}[stage],
            "expected_severity": {"syntax": "error", "semantic": "error", "policy": "warning"}[stage],
        }
        for stage, ok in stage_separation.items()
    )
    expected_exit_codes_by_stage_profile = {"syntax": 1, "semantic": 1, "policy": 0}
    exit_codes_by_stage_profile = {
        result["id"]: result.get("exit_code")
        for result in stage_profile_results
        if result["id"] in expected_exit_codes_by_stage_profile
    }
    missing_stage_profile_exit_code_profiles = tuple(
        profile_id
        for profile_id, expected_exit_code in expected_exit_codes_by_stage_profile.items()
        if exit_codes_by_stage_profile.get(profile_id) != expected_exit_code
    )
    ok_by_stage_profile = {
        result["id"]: result.get("ok") is True
        for result in stage_profile_results
    }
    missing_ok_stage_profiles = tuple(
        profile_id
        for profile_id in expected_exit_codes_by_stage_profile
        if ok_by_stage_profile.get(profile_id) is not True
    )
    return {
        "format": "appgen.lint-directory-cli-audit.v1",
        "ok": exit_code == 0
        and payload.get("format") == "appgen.lint-report.v1"
        and payload.get("ok") is True
        and payload.get("source_mode") == "directory"
        and len(files) == 2
        and file_order_sorted
        and len(file_reports) == 2
        and payload.get("strict") is True
        and payload.get("component_catalog", {}).get("components") == ["CustomGauge"]
        and warning_exit_code == 0
        and warning_payload.get("format") == "appgen.lint-report.v1"
        and warning_payload.get("source_mode") == "directory"
        and warning_severity_counts.get("warning", 0) >= 1
        and len(warning_diagnostics) >= 1
        and warning_diagnostics_have_files
        and normal_unknown_component_warning
        and strict_unknown_component_error
        and strict_catalog_component_success
        and migration_lint_success
        and all(stage_separation.values())
        and not missing_exit_code_scenarios
        and not missing_payload_format_scenarios
        and not missing_ok_scenarios
        and not missing_stage_profile_exit_code_profiles
        and not missing_ok_stage_profiles
        and not missing_stage_names
        and not missing_severity_names,
        "scenario_count": len(scenario_results),
        "passing_scenario_count": sum(1 for result in scenario_results if result["ok"]),
        "failing_scenario_count": len(failing_scenarios),
        "failing_scenarios": failing_scenarios,
        "scenario_ids": tuple(result["id"] for result in scenario_results),
        "scenarios": scenario_results,
        "required_scenario_ids": required_scenario_ids,
        "expected_exit_codes_by_scenario": expected_exit_codes_by_scenario,
        "exit_codes_by_scenario": exit_codes_by_scenario,
        "missing_exit_code_scenario_count": len(missing_exit_code_scenarios),
        "missing_exit_code_scenarios": missing_exit_code_scenarios,
        "expected_payload_formats_by_scenario": expected_payload_formats_by_scenario,
        "payload_formats_by_scenario": payload_formats_by_scenario,
        "missing_payload_format_scenario_count": len(missing_payload_format_scenarios),
        "missing_payload_format_scenarios": missing_payload_format_scenarios,
        "ok_by_scenario": ok_by_scenario,
        "missing_ok_scenario_count": len(missing_ok_scenarios),
        "missing_ok_scenarios": missing_ok_scenarios,
        "stage_profile_count": len(stage_separation),
        "passing_stage_profile_count": sum(1 for result in stage_profile_results if result["ok"]),
        "failing_stage_profile_count": sum(1 for result in stage_profile_results if not result["ok"]),
        "stage_profile_ids": tuple(result["id"] for result in stage_profile_results),
        "stage_profiles": stage_profile_results,
        "expected_exit_codes_by_stage_profile": expected_exit_codes_by_stage_profile,
        "exit_codes_by_stage_profile": exit_codes_by_stage_profile,
        "missing_stage_profile_exit_code_count": len(missing_stage_profile_exit_code_profiles),
        "missing_stage_profile_exit_code_profiles": missing_stage_profile_exit_code_profiles,
        "ok_by_stage_profile": ok_by_stage_profile,
        "missing_ok_stage_profile_count": len(missing_ok_stage_profiles),
        "missing_ok_stage_profiles": missing_ok_stage_profiles,
        "required_stage_names": required_stage_names,
        "observed_stage_names": observed_stage_names,
        "missing_stage_name_count": len(missing_stage_names),
        "missing_stage_names": missing_stage_names,
        "required_severity_names": required_severity_names,
        "observed_severity_names": observed_severity_names,
        "missing_severity_name_count": len(missing_severity_names),
        "missing_severity_names": missing_severity_names,
        "exit_code": exit_code,
        "payload_format": payload.get("format"),
        "source_mode": payload.get("source_mode"),
        "files": files,
        "file_order_sorted": file_order_sorted,
        "file_relative_order": file_relative_order,
        "file_report_count": len(file_reports),
        "strict": payload.get("strict"),
        "component_catalog": payload.get("component_catalog"),
        "warning_exit_code": warning_exit_code,
        "warning_source_mode": warning_payload.get("source_mode"),
        "warning_count": warning_severity_counts.get("warning", 0),
        "diagnostic_count": len(warning_diagnostics),
        "diagnostics_have_files": warning_diagnostics_have_files,
        "normal_unknown_component_warning": {
            "ok": normal_unknown_component_warning,
            "exit_code": normal_unknown_exit_code,
            "strict": normal_unknown_payload.get("strict"),
            "severity_counts": normal_unknown_payload.get("severity_counts"),
        },
        "strict_unknown_component_error": {
            "ok": strict_unknown_component_error,
            "exit_code": strict_unknown_exit_code,
            "strict": strict_unknown_payload.get("strict"),
            "severity_counts": strict_unknown_payload.get("severity_counts"),
        },
        "strict_catalog_component_success": {
            "ok": strict_catalog_component_success,
            "exit_code": strict_catalog_exit_code,
            "strict": strict_catalog_payload.get("strict"),
            "component_catalog": strict_catalog_payload.get("component_catalog"),
        },
        "previous_semantic_migration_preview": {
            "ok": migration_lint_success,
            "exit_code": migration_exit_code,
            "format": migration_preview.get("format"),
            "backend": migration_preview.get("backend"),
            "detected": tuple(migration_preview.get("coverage", {}).get("detected", ())),
        },
        "stage_separation": {
            "ok": all(stage_separation.values()),
            "stage_names": syntax_payload.get("stage_names", ()),
            "severity_names": syntax_payload.get("severity_names", ()),
            "stages": stage_separation,
            "syntax": syntax_payload.get("stages", {}),
            "semantic": semantic_payload.get("stages", {}),
            "policy": policy_payload.get("stages", {}),
        },
    }


def _tooling_audit_validate_generate_cli(tmp: Path, source: str) -> dict:
    source_path = tmp / "validate-generate.appgen"
    web_only_path = tmp / "validate-web-only.appgen"
    warning_path = tmp / "warning-generate.appgen"
    error_path = tmp / "error-generate.appgen"
    output_dir = tmp / "generated-cli"
    warning_blocked_dir = tmp / "warning-blocked-cli"
    warning_allowed_dir = tmp / "warning-allowed-cli"
    error_allowed_dir = tmp / "error-allowed-cli"
    source_path.write_text(source, encoding="utf-8")
    web_only_path.write_text("app WebOnly { targets: web }\n\ntable Thing { id: int pk }\n", encoding="utf-8")
    warning_path.write_text(_tooling_audit_warning_generation_sample(), encoding="utf-8")
    error_path.write_text("app Bad { targets: web }\n\ntable Invoice { total: galaxy }\n", encoding="utf-8")

    def run_json(argv: tuple[str, ...]) -> tuple[int, dict]:
        output = io.StringIO()
        with contextlib.redirect_stdout(output):
            exit_code = dsl_tooling_cli(argv)
        try:
            payload = json.loads(output.getvalue())
        except json.JSONDecodeError:
            payload = {}
        return exit_code, payload

    validate_exit, validate_payload = run_json(
        ("validate", str(source_path), "--targets", "web,mobile,desktop", "--json")
    )
    missing_target_exit, missing_target_payload = run_json(
        ("validate", str(web_only_path), "--targets", "web,mobile", "--json")
    )
    unknown_target_exit, unknown_target_payload = run_json(
        ("validate", str(web_only_path), "--targets", "satellite", "--json")
    )
    generate_exit, generate_payload = run_json(
        ("generate", str(source_path), "--target", "web", "--out", str(output_dir), "--json")
    )
    generate_artifacts = tuple(generate_payload.get("artifacts", ()))
    generate_artifact_paths_exist = all(
        (output_dir / str(artifact.get("path", ""))).exists() for artifact in generate_artifacts
    )
    generate_manifest_path = Path(str(generate_payload.get("manifest", "")))
    try:
        generate_manifest = json.loads(generate_manifest_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        generate_manifest = {}
    warning_blocked_exit, warning_blocked_payload = run_json(
        ("generate", str(warning_path), "--out", str(warning_blocked_dir), "--json")
    )
    warning_allowed_exit, warning_allowed_payload = run_json(
        ("generate", str(warning_path), "--out", str(warning_allowed_dir), "--allow-warnings", "--json")
    )
    error_allowed_exit, error_allowed_payload = run_json(
        ("generate", str(error_path), "--out", str(error_allowed_dir), "--allow-warnings", "--json")
    )
    cases = (
        {
            "case": "validate_targets",
            "ok": validate_exit == 0
            and validate_payload.get("format") == "appgen.validate-report.v1"
            and tuple(validate_payload.get("requested_targets", ())) == ("web", "mobile", "desktop")
            and any(
                check.get("check") == "target_compatibility" and check.get("ok")
                for check in validate_payload.get("checks", ())
            ),
            "exit_code": validate_exit,
            "payload_format": validate_payload.get("format"),
            "requested_targets": tuple(validate_payload.get("requested_targets", ())),
        },
        {
            "case": "validate_rejects_undeclared_targets",
            "ok": missing_target_exit == 1
            and missing_target_payload.get("format") == "appgen.validate-report.v1"
            and missing_target_payload.get("ok") is False
            and tuple(missing_target_payload.get("requested_targets", ())) == ("web", "mobile")
            and tuple(missing_target_payload.get("app_targets", ())) == ("web",)
            and any(
                check.get("check") == "target_compatibility"
                and tuple(check.get("missing_targets", ())) == ("mobile",)
                for check in missing_target_payload.get("checks", ())
            )
            and any(item.get("code") == "AGX0802" for item in missing_target_payload.get("diagnostics", ())),
            "exit_code": missing_target_exit,
            "payload_format": missing_target_payload.get("format"),
            "requested_targets": tuple(missing_target_payload.get("requested_targets", ())),
            "app_targets": tuple(missing_target_payload.get("app_targets", ())),
            "diagnostic_codes": tuple(item.get("code") for item in missing_target_payload.get("diagnostics", ())),
        },
        {
            "case": "validate_rejects_unknown_targets",
            "ok": unknown_target_exit == 1
            and unknown_target_payload.get("format") == "appgen.validate-report.v1"
            and unknown_target_payload.get("ok") is False
            and any(
                check.get("check") == "target_compatibility"
                and tuple(check.get("unknown_targets", ())) == ("satellite",)
                for check in unknown_target_payload.get("checks", ())
            )
            and any(item.get("code") == "AGX0802" for item in unknown_target_payload.get("diagnostics", ())),
            "exit_code": unknown_target_exit,
            "payload_format": unknown_target_payload.get("format"),
            "requested_targets": tuple(unknown_target_payload.get("requested_targets", ())),
            "diagnostic_codes": tuple(item.get("code") for item in unknown_target_payload.get("diagnostics", ())),
        },
        {
            "case": "generate_writes_artifacts",
            "ok": generate_exit == 0
            and generate_payload.get("format") == "appgen.generate-report.v1"
            and generate_payload.get("generated") is True
            and tuple(generate_payload.get("targets", ())) == ("web",)
            and generate_payload.get("output_dir") == str(output_dir)
            and generate_payload.get("semantic_model_format") == "appgen.semantic-model.v1"
            and generate_payload.get("validation", {}).get("format") == "appgen.validate-report.v1"
            and generate_manifest_path.exists()
            and bool(generate_manifest.get("app_name"))
            and bool(generate_artifacts)
            and generate_artifact_paths_exist,
            "exit_code": generate_exit,
            "payload_format": generate_payload.get("format"),
            "targets": tuple(generate_payload.get("targets", ())),
            "output_dir": generate_payload.get("output_dir"),
            "semantic_model_format": generate_payload.get("semantic_model_format"),
            "validation_format": generate_payload.get("validation", {}).get("format"),
            "artifact_count": len(generate_artifacts),
            "artifact_paths_exist": generate_artifact_paths_exist,
            "manifest": generate_payload.get("manifest"),
            "manifest_exists": generate_manifest_path.exists(),
            "manifest_app_name": generate_manifest.get("app_name"),
        },
        {
            "case": "generate_blocks_warnings",
            "ok": warning_blocked_exit == 1
            and warning_blocked_payload.get("format") == "appgen.generate-report.v1"
            and warning_blocked_payload.get("generated") is False
            and "lint_warnings" in warning_blocked_payload.get("blocking_gaps", ()),
            "exit_code": warning_blocked_exit,
            "payload_format": warning_blocked_payload.get("format"),
            "blocking_gaps": tuple(warning_blocked_payload.get("blocking_gaps", ())),
        },
        {
            "case": "generate_allows_warnings_when_requested",
            "ok": warning_allowed_exit == 0
            and warning_allowed_payload.get("format") == "appgen.generate-report.v1"
            and warning_allowed_payload.get("generated") is True
            and warning_allowed_payload.get("allow_warnings") is True
            and Path(str(warning_allowed_payload.get("manifest", ""))).exists(),
            "exit_code": warning_allowed_exit,
            "payload_format": warning_allowed_payload.get("format"),
            "allow_warnings": warning_allowed_payload.get("allow_warnings"),
            "manifest": warning_allowed_payload.get("manifest"),
        },
        {
            "case": "generate_blocks_errors_even_when_warnings_allowed",
            "ok": error_allowed_exit == 1
            and error_allowed_payload.get("format") == "appgen.generate-report.v1"
            and error_allowed_payload.get("generated") is False
            and error_allowed_payload.get("allow_warnings") is True
            and "lint_errors" in error_allowed_payload.get("blocking_gaps", ())
            and not error_allowed_dir.exists(),
            "exit_code": error_allowed_exit,
            "payload_format": error_allowed_payload.get("format"),
            "allow_warnings": error_allowed_payload.get("allow_warnings"),
            "blocking_gaps": tuple(error_allowed_payload.get("blocking_gaps", ())),
            "output_exists": error_allowed_dir.exists(),
        },
    )
    failing_cases = tuple(case["case"] for case in cases if not case["ok"])
    generated_cases = tuple(case for case in cases if case.get("case", "").startswith("generate_"))
    validation_cases = tuple(case for case in cases if case.get("case", "").startswith("validate_"))
    generated_success_cases = tuple(case["case"] for case in generated_cases if case.get("ok") and case.get("exit_code") == 0)
    generated_blocked_cases = tuple(
        case["case"]
        for case in generated_cases
        if case.get("ok") and case.get("exit_code") == 1 and case.get("blocking_gaps")
    )
    validation_rejection_cases = tuple(
        case["case"]
        for case in validation_cases
        if case.get("ok") and case.get("exit_code") == 1 and case.get("diagnostic_codes")
    )
    manifest_existing_cases = tuple(
        case["case"]
        for case in generated_cases
        if case.get("manifest_exists") is True
        or (case.get("manifest") and Path(str(case.get("manifest"))).exists())
    )
    artifact_path_case_count = sum(
        1 for case in generated_cases if case.get("artifact_paths_exist") is True
    )
    generated_blocked_output_absent_cases = tuple(
        case["case"]
        for case in generated_cases
        if case.get("exit_code") == 1
        and case.get("blocking_gaps")
        and case.get("output_exists") is False
    )
    generated_blocking_gap_names = tuple(
        dict.fromkeys(
            gap
            for case in generated_cases
            for gap in case.get("blocking_gaps", ())
        )
    )
    payload_formats = tuple(dict.fromkeys(case.get("payload_format") for case in cases if case.get("payload_format")))
    case_ids = tuple(case["case"] for case in cases)
    required_case_ids = (
        "validate_targets",
        "validate_rejects_undeclared_targets",
        "validate_rejects_unknown_targets",
        "generate_writes_artifacts",
        "generate_blocks_warnings",
        "generate_allows_warnings_when_requested",
        "generate_blocks_errors_even_when_warnings_allowed",
    )
    missing_case_ids = tuple(case_id for case_id in required_case_ids if case_id not in case_ids)
    expected_payload_formats_by_case = {
        "validate_targets": "appgen.validate-report.v1",
        "validate_rejects_undeclared_targets": "appgen.validate-report.v1",
        "validate_rejects_unknown_targets": "appgen.validate-report.v1",
        "generate_writes_artifacts": "appgen.generate-report.v1",
        "generate_blocks_warnings": "appgen.generate-report.v1",
        "generate_allows_warnings_when_requested": "appgen.generate-report.v1",
        "generate_blocks_errors_even_when_warnings_allowed": "appgen.generate-report.v1",
    }
    payload_formats_by_case = {
        case["case"]: case.get("payload_format")
        for case in cases
        if case["case"] in expected_payload_formats_by_case
    }
    missing_payload_format_cases = tuple(
        case_id
        for case_id, expected_format in expected_payload_formats_by_case.items()
        if payload_formats_by_case.get(case_id) != expected_format
    )
    expected_exit_codes_by_case = {
        "validate_targets": 0,
        "validate_rejects_undeclared_targets": 1,
        "validate_rejects_unknown_targets": 1,
        "generate_writes_artifacts": 0,
        "generate_blocks_warnings": 1,
        "generate_allows_warnings_when_requested": 0,
        "generate_blocks_errors_even_when_warnings_allowed": 1,
    }
    exit_codes_by_case = {
        case["case"]: case.get("exit_code")
        for case in cases
        if case["case"] in expected_exit_codes_by_case
    }
    missing_exit_code_cases = tuple(
        case_id
        for case_id, expected_exit_code in expected_exit_codes_by_case.items()
        if exit_codes_by_case.get(case_id) != expected_exit_code
    )
    ok_by_case = {
        case["case"]: case.get("ok") is True
        for case in cases
        if case["case"] in required_case_ids
    }
    missing_ok_cases = tuple(
        case_id
        for case_id in required_case_ids
        if ok_by_case.get(case_id) is not True
    )
    return {
        "format": "appgen.validate-generate-cli-audit.v1",
        "ok": not failing_cases
        and not missing_case_ids
        and not missing_payload_format_cases
        and not missing_exit_code_cases
        and not missing_ok_cases,
        "case_count": len(cases),
        "passing_case_count": sum(1 for case in cases if case["ok"]),
        "failing_case_count": len(failing_cases),
        "required_case_ids": required_case_ids,
        "observed_case_ids": case_ids,
        "missing_case_count": len(missing_case_ids),
        "missing_case_ids": missing_case_ids,
        "case_ids": case_ids,
        "failing_cases": failing_cases,
        "generated_case_count": len(generated_cases),
        "validation_case_count": len(validation_cases),
        "generated_success_case_count": len(generated_success_cases),
        "generated_success_cases": generated_success_cases,
        "generated_blocked_case_count": len(generated_blocked_cases),
        "generated_blocked_cases": generated_blocked_cases,
        "validation_rejection_case_count": len(validation_rejection_cases),
        "validation_rejection_cases": validation_rejection_cases,
        "manifest_case_count": sum(1 for case in generated_cases if case.get("manifest") or case.get("manifest_exists")),
        "manifest_existing_case_count": len(manifest_existing_cases),
        "manifest_existing_cases": manifest_existing_cases,
        "artifact_handoff_case_count": sum(1 for case in generated_cases if case.get("artifact_count", 0) > 0),
        "artifact_path_case_count": artifact_path_case_count,
        "artifact_path_missing_case_count": sum(
            1
            for case in generated_cases
            if case.get("artifact_count", 0) > 0 and case.get("artifact_paths_exist") is not True
        ),
        "blocking_gap_case_count": sum(1 for case in cases if case.get("blocking_gaps")),
        "generated_blocked_output_absent_case_count": len(generated_blocked_output_absent_cases),
        "generated_blocked_output_absent_cases": generated_blocked_output_absent_cases,
        "generated_blocking_gap_names": generated_blocking_gap_names,
        "expected_payload_formats_by_case": expected_payload_formats_by_case,
        "payload_formats_by_case": payload_formats_by_case,
        "missing_payload_format_case_count": len(missing_payload_format_cases),
        "missing_payload_format_cases": missing_payload_format_cases,
        "expected_exit_codes_by_case": expected_exit_codes_by_case,
        "exit_codes_by_case": exit_codes_by_case,
        "missing_exit_code_case_count": len(missing_exit_code_cases),
        "missing_exit_code_cases": missing_exit_code_cases,
        "ok_by_case": ok_by_case,
        "missing_ok_case_count": len(missing_ok_cases),
        "missing_ok_cases": missing_ok_cases,
        "payload_format_count": len(payload_formats),
        "payload_formats": payload_formats,
        "cases": cases,
    }


def _tooling_audit_semantic_source_set_cli(tmp: Path) -> dict:
    source_dir = tmp / "semantic-source-set"
    (source_dir / "data").mkdir(parents=True, exist_ok=True)
    (source_dir / "ui").mkdir(parents=True, exist_ok=True)
    (source_dir / "workflow").mkdir(parents=True, exist_ok=True)
    app_path = source_dir / "app.appgen"
    customer_path = source_dir / "data" / "customer.appgen"
    invoice_path = source_dir / "data" / "invoice.appgen"
    form_path = source_dir / "ui" / "invoice-form.appgen"
    flow_path = source_dir / "workflow" / "submit-invoice.appgen"
    app_path.write_text("app WorkspaceFinance { targets: web, mobile, desktop }\n", encoding="utf-8")
    customer_path.write_text(
        "table Customer { id: int pk; name: string required search; email: string }\n",
        encoding="utf-8",
    )
    invoice_path.write_text(
        """
table Invoice {
  id: int pk
  customer_id: int -> Customer.id [many-to-one]
  subtotal: decimal default 0
  tax: decimal default 0
  total: decimal = subtotal + tax
  lookup customer_name (customer.name)
}
""".strip()
        + "\n",
        encoding="utf-8",
    )
    form_path.write_text(
        """
view InvoiceForm for Invoice {
  Main: customer.name, total
  @ customer.name Lookup 0 0 6 1
  on Save -> SubmitInvoice
}
""".strip()
        + "\n",
        encoding="utf-8",
    )
    flow_path.write_text("flow SubmitInvoice { draft -> reviewed; reviewed -> posted }\n", encoding="utf-8")
    json_exit, payload = _tooling_cli_json_case(("semantic", str(source_dir), "--json"))
    text_exit, text_output = _tooling_cli_text_case(("semantic", str(source_dir)))
    expected_files = tuple(str(path) for path in (app_path, customer_path, invoice_path, form_path, flow_path))
    symbols = payload.get("symbols") or {}
    source_file_symbol_counts = payload.get("source_file_symbol_counts") or {}
    symbol_files_by_id = {
        symbol_id: symbol.get("file")
        for symbol_id, symbol in symbols.items()
        if symbol_id in {"app.WorkspaceFinance", "table.Customer", "table.Invoice", "view.InvoiceForm", "flow.SubmitInvoice"}
    }
    required_symbol_files_by_id = {
        "app.WorkspaceFinance": str(app_path),
        "table.Customer": str(customer_path),
        "table.Invoice": str(invoice_path),
        "view.InvoiceForm": str(form_path),
        "flow.SubmitInvoice": str(flow_path),
    }
    missing_symbol_file_ids = tuple(
        symbol_id
        for symbol_id, expected_file in required_symbol_files_by_id.items()
        if symbol_files_by_id.get(symbol_id) != expected_file
    )
    required_text_markers = (
        "semantic ok: format=appgen.semantic-model.v1",
        "source_mode=directory",
        "source_set_format=appgen.semantic-source-set.v1",
        "symbol-coverage format=appgen.symbol-coverage.v1",
        "contract-counts",
        *tuple(f"source-file {file_name}" for file_name in expected_files),
        *tuple(f"symbol-file {file_name}" for file_name in expected_files),
    )
    missing_text_markers = tuple(marker for marker in required_text_markers if marker not in text_output)
    diagnostics = tuple(payload.get("diagnostics", ()))
    error_diagnostics = tuple(item for item in diagnostics if item.get("severity") == "error")
    required_tables = ("Customer", "Invoice")
    required_views = ("InvoiceForm",)
    required_flows = ("SubmitInvoice",)
    missing_tables = tuple(name for name in required_tables if name not in (payload.get("tables") or {}))
    missing_views = tuple(name for name in required_views if name not in (payload.get("views") or {}))
    missing_flows = tuple(name for name in required_flows if name not in (payload.get("flows") or {}))
    source_files = tuple(payload.get("source_files", ()))
    missing_files = tuple(file_name for file_name in expected_files if file_name not in source_files)
    files_without_symbols = tuple(file_name for file_name in expected_files if source_file_symbol_counts.get(file_name, 0) < 1)
    ok = (
        json_exit == 0
        and text_exit == 0
        and payload.get("format") == "appgen.semantic-model.v1"
        and payload.get("ok") is True
        and payload.get("source_mode") == "directory"
        and payload.get("source_set", {}).get("format") == "appgen.semantic-source-set.v1"
        and payload.get("file_count") == len(expected_files)
        and not missing_files
        and not error_diagnostics
        and not missing_tables
        and not missing_views
        and not missing_flows
        and not missing_symbol_file_ids
        and not files_without_symbols
        and not missing_text_markers
        and not text_output.lstrip().startswith("{")
    )
    return {
        "format": "appgen.semantic-source-set-cli-audit.v1",
        "ok": ok,
        "json_exit_code": json_exit,
        "text_exit_code": text_exit,
        "payload_format": payload.get("format"),
        "source_set_format": payload.get("source_set", {}).get("format"),
        "source_mode": payload.get("source_mode"),
        "file_count": payload.get("file_count"),
        "expected_file_count": len(expected_files),
        "source_files": source_files,
        "expected_files": expected_files,
        "missing_files": missing_files,
        "missing_file_count": len(missing_files),
        "required_tables": required_tables,
        "missing_tables": missing_tables,
        "missing_table_count": len(missing_tables),
        "required_views": required_views,
        "missing_views": missing_views,
        "missing_view_count": len(missing_views),
        "required_flows": required_flows,
        "missing_flows": missing_flows,
        "missing_flow_count": len(missing_flows),
        "symbol_files_by_id": symbol_files_by_id,
        "required_symbol_files_by_id": required_symbol_files_by_id,
        "missing_symbol_file_ids": missing_symbol_file_ids,
        "missing_symbol_file_count": len(missing_symbol_file_ids),
        "source_file_symbol_counts": source_file_symbol_counts,
        "files_without_symbols": files_without_symbols,
        "files_without_symbols_count": len(files_without_symbols),
        "diagnostic_count": len(diagnostics),
        "error_diagnostic_count": len(error_diagnostics),
        "required_text_markers": required_text_markers,
        "missing_text_markers": missing_text_markers,
        "missing_text_marker_count": len(missing_text_markers),
        "text_json_fallback": text_output.lstrip().startswith("{"),
        "text_output_line_count": len(text_output.splitlines()),
    }


def _tooling_cli_json_case(argv: tuple[str, ...]) -> tuple[int, dict]:
    output = io.StringIO()
    with contextlib.redirect_stdout(output):
        exit_code = dsl_tooling_cli(argv)
    try:
        payload = json.loads(output.getvalue())
    except json.JSONDecodeError:
        payload = {}
    return exit_code, payload


def _tooling_cli_text_case(argv: tuple[str, ...]) -> tuple[int, str]:
    output = io.StringIO()
    with contextlib.redirect_stdout(output):
        exit_code = dsl_tooling_cli(argv)
    return exit_code, output.getvalue()


def _tooling_audit_doctor_cli_modes() -> dict:
    json_exit, json_payload = _tooling_cli_json_case(("doctor", "--json"))
    text_exit, text_output = _tooling_cli_text_case(("doctor",))
    required_case_ids = ("doctor_json", "doctor_text")
    required_check_ids = (
        "grammar_file",
        "generated_parser",
        "parser_sync",
        "parser_golden_fixtures",
        "directory_lint_input",
        "python_package_import",
        "sqlalchemy_import",
        "pbc_catalog",
        "template_writers",
        "generator_backends",
        "lsp_semantic_service",
        "cli_alias_contract",
        "lsp_completion_coverage",
        "semantic_symbol_coverage",
        "lsp_symbol_coverage",
        "module_boundaries",
        "studio_semantic_service",
        "vscode_extension_surface",
    )
    observed_check_ids = tuple(check.get("check") for check in json_payload.get("checks", ()))
    missing_required_check_ids = tuple(check_id for check_id in required_check_ids if check_id not in observed_check_ids)
    required_detail_formats_by_check = {
        "parser_sync": "appgen.dsl-antlr-integrity.v1",
        "parser_golden_fixtures": "appgen.parser-golden-audit.v1",
        "directory_lint_input": "appgen.lint-report.v1",
        "lsp_semantic_service": "appgen.lsp-capabilities.v1",
        "cli_alias_contract": "appgen.cli-alias-contract.v1",
        "lsp_completion_coverage": "appgen.completion-coverage.v1",
        "semantic_symbol_coverage": "appgen.symbol-coverage.v1",
        "lsp_symbol_coverage": "appgen.lsp-symbol-coverage.v1",
        "module_boundaries": "appgen.module-boundary-audit.v1",
        "studio_semantic_service": "appgen.designer-sync-report.v1",
        "vscode_extension_surface": "appgen.vscode-extension-audit.v1",
    }
    checks_by_id = {check.get("check"): check for check in json_payload.get("checks", ())}
    detail_formats_by_check = {
        check_id: checks_by_id.get(check_id, {}).get("detail", {}).get("report_format")
        for check_id in required_detail_formats_by_check
    }
    missing_detail_format_checks = tuple(
        check_id
        for check_id, expected_format in required_detail_formats_by_check.items()
        if detail_formats_by_check.get(check_id) != expected_format
    )
    required_text_markers_by_case = {
        "doctor_text": (
            "doctor ok: format=appgen.doctor-report.v1",
            "blocking_gaps=0",
            "detail_format=appgen.parser-golden-audit.v1",
            "detail_format=appgen.cli-alias-contract.v1",
            "detail_format=appgen.completion-coverage.v1",
            "detail_format=appgen.symbol-coverage.v1",
            "detail_format=appgen.lsp-symbol-coverage.v1",
            "detail_format=appgen.module-boundary-audit.v1",
            "detail_format=appgen.designer-sync-report.v1",
            "detail_format=appgen.vscode-extension-audit.v1",
        )
    }
    missing_text_markers_by_case = {
        case_id: tuple(marker for marker in markers if marker not in text_output)
        for case_id, markers in required_text_markers_by_case.items()
    }
    missing_text_marker_cases = tuple(
        case_id for case_id, markers in missing_text_markers_by_case.items() if markers
    )
    cases = (
        {
            "case": "doctor_json",
            "mode": "json",
            "ok": json_exit == 0
            and json_payload.get("format") == "appgen.doctor-report.v1"
            and json_payload.get("ok") is True
            and not json_payload.get("blocking_gaps")
            and not missing_required_check_ids
            and not missing_detail_format_checks,
            "exit_code": json_exit,
            "payload_format": json_payload.get("format"),
            "check_count": len(json_payload.get("checks", ())),
            "blocking_gap_count": len(json_payload.get("blocking_gaps", ())),
        },
        {
            "case": "doctor_text",
            "mode": "text",
            "ok": text_exit == 0
            and not missing_text_marker_cases
            and not text_output.lstrip().startswith("{"),
            "exit_code": text_exit,
            "payload_format": None,
            "json_fallback": text_output.lstrip().startswith("{"),
            "text_prefix": text_output[:160],
        },
    )
    expected_modes_by_case = {"doctor_json": "json", "doctor_text": "text"}
    modes_by_case = {case["case"]: case["mode"] for case in cases}
    missing_mode_cases = tuple(
        case_id for case_id, expected_mode in expected_modes_by_case.items() if modes_by_case.get(case_id) != expected_mode
    )
    expected_exit_codes_by_case = {case_id: 0 for case_id in required_case_ids}
    exit_codes_by_case = {case["case"]: case["exit_code"] for case in cases}
    missing_exit_code_cases = tuple(
        case_id
        for case_id, expected_exit_code in expected_exit_codes_by_case.items()
        if exit_codes_by_case.get(case_id) != expected_exit_code
    )
    ok_by_case = {case["case"]: case["ok"] is True for case in cases}
    missing_ok_cases = tuple(case_id for case_id in required_case_ids if ok_by_case.get(case_id) is not True)
    expected_payload_formats_by_case = {"doctor_json": "appgen.doctor-report.v1"}
    payload_formats_by_case = {"doctor_json": json_payload.get("format")}
    missing_payload_format_cases = tuple(
        case_id
        for case_id, expected_format in expected_payload_formats_by_case.items()
        if payload_formats_by_case.get(case_id) != expected_format
    )
    text_json_fallback_by_case = {"doctor_text": text_output.lstrip().startswith("{")}
    text_json_fallback_cases = tuple(
        case_id for case_id, has_fallback in text_json_fallback_by_case.items() if has_fallback
    )
    observed_case_ids = tuple(case["case"] for case in cases)
    missing_case_ids = tuple(case_id for case_id in required_case_ids if case_id not in observed_case_ids)
    failing_cases = tuple(case["case"] for case in cases if case["ok"] is not True)
    return {
        "format": "appgen.doctor-cli-audit.v1",
        "ok": not missing_case_ids
        and not failing_cases
        and not missing_mode_cases
        and not missing_exit_code_cases
        and not missing_ok_cases
        and not missing_payload_format_cases
        and not missing_required_check_ids
        and not missing_detail_format_checks
        and not missing_text_marker_cases
        and not text_json_fallback_cases,
        "case_count": len(cases),
        "passing_case_count": sum(1 for case in cases if case["ok"] is True),
        "failing_case_count": len(failing_cases),
        "failing_cases": failing_cases,
        "required_case_ids": required_case_ids,
        "observed_case_ids": observed_case_ids,
        "missing_case_count": len(missing_case_ids),
        "missing_case_ids": missing_case_ids,
        "expected_modes_by_case": expected_modes_by_case,
        "modes_by_case": modes_by_case,
        "missing_mode_case_count": len(missing_mode_cases),
        "missing_mode_cases": missing_mode_cases,
        "expected_exit_codes_by_case": expected_exit_codes_by_case,
        "exit_codes_by_case": exit_codes_by_case,
        "missing_exit_code_case_count": len(missing_exit_code_cases),
        "missing_exit_code_cases": missing_exit_code_cases,
        "ok_by_case": ok_by_case,
        "missing_ok_case_count": len(missing_ok_cases),
        "missing_ok_cases": missing_ok_cases,
        "expected_payload_formats_by_case": expected_payload_formats_by_case,
        "payload_formats_by_case": payload_formats_by_case,
        "missing_payload_format_case_count": len(missing_payload_format_cases),
        "missing_payload_format_cases": missing_payload_format_cases,
        "required_check_ids": required_check_ids,
        "observed_check_ids": observed_check_ids,
        "missing_required_check_count": len(missing_required_check_ids),
        "missing_required_check_ids": missing_required_check_ids,
        "required_detail_formats_by_check": required_detail_formats_by_check,
        "detail_formats_by_check": detail_formats_by_check,
        "missing_detail_format_check_count": len(missing_detail_format_checks),
        "missing_detail_format_checks": missing_detail_format_checks,
        "required_text_markers_by_case": required_text_markers_by_case,
        "missing_text_markers_by_case": missing_text_markers_by_case,
        "missing_text_marker_case_count": len(missing_text_marker_cases),
        "missing_text_marker_cases": missing_text_marker_cases,
        "missing_text_marker_count": sum(len(markers) for markers in missing_text_markers_by_case.values()),
        "text_json_fallback_by_case": text_json_fallback_by_case,
        "text_json_fallback_case_count": len(text_json_fallback_cases),
        "text_json_fallback_cases": text_json_fallback_cases,
        "doctor_check_count": len(json_payload.get("checks", ())),
        "blocking_gap_count": len(json_payload.get("blocking_gaps", ())),
        "cases": cases,
    }


def _tooling_audit_pbc_cli_text() -> dict:
    list_exit, list_text = _tooling_cli_text_case(("pbc", "list"))
    verify_exit, verify_text = _tooling_cli_text_case(("pbc", "verify", "gl_core"))
    cases = (
        {
            "case": "pbc_list_text",
            "ok": list_exit == 0
            and list_text.startswith("pbc list ok: count=")
            and "format=appgen.pbc-verifier-catalog.v1" in list_text
            and "mesh " in list_text
            and "pbc gl_core: ok=True" in list_text
            and not list_text.lstrip().startswith("{"),
            "exit_code": list_exit,
            "has_catalog_format": "format=appgen.pbc-verifier-catalog.v1" in list_text,
            "has_mesh_counts": "mesh " in list_text,
            "has_catalog_entry": "pbc gl_core: ok=True" in list_text,
            "json_fallback": list_text.lstrip().startswith("{"),
        },
        {
            "case": "pbc_verify_text",
            "ok": verify_exit == 0
            and verify_text.startswith("pbc verify ok: pbc=gl_core")
            and "format=appgen.pbc-package-verifier.v1" in verify_text
            and "checks=7 gaps=0" in verify_text
            and "ok manifest_validates" in verify_text
            and "catalog label=" in verify_text
            and not verify_text.lstrip().startswith("{"),
            "exit_code": verify_exit,
            "has_verifier_format": "format=appgen.pbc-package-verifier.v1" in verify_text,
            "has_check_counts": "checks=7 gaps=0" in verify_text,
            "has_per_check_status": "ok manifest_validates" in verify_text,
            "has_catalog_metadata": "catalog label=" in verify_text,
            "json_fallback": verify_text.lstrip().startswith("{"),
        },
    )
    return {
        "format": "appgen.pbc-cli-text-audit.v1",
        "ok": all(case["ok"] for case in cases),
        "case_count": len(cases),
        "passing_case_count": sum(1 for case in cases if case["ok"]),
        "failing_case_count": sum(1 for case in cases if not case["ok"]),
        "json_fallback_count": sum(1 for case in cases if case.get("json_fallback")),
        "cases": cases,
    }


def _tooling_audit_pbc_publish_cli(tmp: Path) -> dict:
    catalog_path = tmp / "pbc-catalog.json"
    pbc_ref = "src/pyAppGen/pbcs/gl_core"
    json_exit, json_payload = _tooling_cli_json_case(
        ("pbc", "publish", pbc_ref, "--catalog", "file", "--catalog-path", str(catalog_path), "--json")
    )
    text_exit, text_output = _tooling_cli_text_case(
        ("pbc", "publish", pbc_ref, "--catalog", "file", "--catalog-path", str(catalog_path))
    )
    patch = json_payload.get("catalog_patch", {}) or {}
    target = json_payload.get("target", {}) or {}
    release_evidence = json_payload.get("release_evidence", {}) or {}
    checks = tuple(json_payload.get("checks", ()))
    cases = (
        {
            "case": "json_publish_plan",
            "ok": json_exit == 0
            and json_payload.get("format") == "appgen.pbc-publish-report.v1"
            and json_payload.get("ok") is True
            and json_payload.get("pbc") == "gl_core"
            and target.get("mode") == "file"
            and target.get("catalog_path") == str(catalog_path)
            and target.get("side_effect_free") is True
            and target.get("write_performed") is False
            and "gl_core" in patch
            and release_evidence.get("format") == "appgen.pbc-package-verifier.v1"
            and release_evidence.get("ok") is True
            and len(checks) >= 6
            and all(check.get("ok") is True for check in checks)
            and not json_payload.get("blocking_gaps"),
        },
        {
            "case": "text_publish_markers",
            "ok": text_exit == 0
            and text_output.startswith("pbc publish ok: gl_core -> file")
            and f"catalog_path {catalog_path}" in text_output
            and "side_effect_free=True write_performed=False" in text_output
            and "catalog-patch gl_core:" in text_output
            and "ok manifest_validates" in text_output
            and "ok publish_is_side_effect_free" in text_output
            and not text_output.lstrip().startswith("{"),
        },
    )
    failing_cases = tuple(case["case"] for case in cases if not case["ok"])
    return {
        "format": "appgen.pbc-publish-cli-audit.v1",
        "ok": not failing_cases,
        "case_count": len(cases),
        "passing_case_count": sum(1 for case in cases if case["ok"]),
        "failing_case_count": len(failing_cases),
        "failing_cases": failing_cases,
        "payload_format": json_payload.get("format"),
        "pbc": json_payload.get("pbc"),
        "target_mode": target.get("mode"),
        "catalog_path": target.get("catalog_path"),
        "side_effect_free": target.get("side_effect_free"),
        "write_performed": target.get("write_performed"),
        "catalog_patch_count": len(patch),
        "release_evidence_format": release_evidence.get("format"),
        "release_evidence_ok": release_evidence.get("ok"),
        "check_count": len(checks),
        "passing_check_count": sum(1 for check in checks if check.get("ok") is True),
        "blocking_gap_count": len(json_payload.get("blocking_gaps", ())),
        "text_exit_code": text_exit,
        "text_has_catalog_path": f"catalog_path {catalog_path}" in text_output,
        "text_has_side_effect_markers": "side_effect_free=True write_performed=False" in text_output,
        "text_has_catalog_patch": "catalog-patch gl_core:" in text_output,
        "text_has_check_status": "ok manifest_validates" in text_output
        and "ok publish_is_side_effect_free" in text_output,
        "text_json_fallback": text_output.lstrip().startswith("{"),
        "cases": cases,
    }


def _tooling_audit_diagnostics_catalog_cli() -> dict:
    catalog_exit, catalog_payload = _tooling_cli_json_case(("diagnostics", "--json"))
    return {
        "case": "diagnostics_catalog",
        "ok": catalog_exit == 0
        and catalog_payload.get("format") == "appgen.diagnostic-catalog.v1"
        and catalog_payload.get("ok") is True
        and not catalog_payload.get("missing_fixtures")
        and set(catalog_payload.get("required_codes", ())) == set(catalog_payload.get("covered_fixture_codes", ())),
        "exit_code": catalog_exit,
        "payload_format": catalog_payload.get("format"),
        "required_count": len(catalog_payload.get("required_codes", ())),
        "covered_count": len(catalog_payload.get("covered_fixture_codes", ())),
        "fixture_count": catalog_payload.get("fixture_count"),
    }


def test_strategy_report_dsl(source: str, *, source_name: str = "<memory>") -> dict:
    """Run the first-class test strategy gate for one DSL source file."""
    with tempfile.TemporaryDirectory(prefix="appgen-test-strategy-") as tmp:
        report = _tooling_audit_test_strategy_cli(Path(tmp), source)
    return {
        **report,
        "source_name": source_name,
        "source_of_truth": "docs/tooling.md#test-strategy",
    }


